 return {
 ownerId: event.ownerId,
 deploymentId: event.deploymentId,
 projectId: event.projectId,
 path: event.cron.path,
 schedule: event.cron.schedule,
 host: event.cron.host,
 timestampInMs,
 awsRequestId: context.awsRequestId,
 };
 };

