import Foundation

// define some constants for the phrase you want to work with
let initialPhrase = "Life is worth living"
let separator = ""

func rearrangePhrase(phrase: String) -> String {

    var newPhrase = ""
    for character in phrase {
        if character == separator {
            continue
        } else {
            newPhrase += character
        }
    }

    // add the phrase back into the new string after separating each word
    newPhrase += initialPhrase
    return newPhrase
}

