response:
1. The redis.js file needs to contain the following code:

class RedisClient {
    constructor(host = 'localhost', port = 6379) {
        this.host = host;
        this.port = port;
        this.connection = new Redis(host, port);
    }

    get(key) {
        return this.connection.get(key);
    }

    set(key, value, expires = 0) {
        if (expires === 0) {
            this.connection.setex(key, 0, value);
        } else {
            this.connection.setex(key, expires, value);
        }
    }

    del(key) {
        this.connection.del(key);
    }

    isAlive() {
        return this.connection.ping();
    }
}

